import{_ as o,o as t,c as n,a2 as r}from"./chunks/framework.CTx8wfac.js";const h=JSON.parse('{"title":"Philosophy","description":"","frontmatter":{},"headers":[],"relativePath":"guide/philosophy.md","filePath":"guide/philosophy.md"}'),s={name:"guide/philosophy.md"};function a(i,e,d,g,c,l){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="philosophy" tabindex="-1">Philosophy <a class="header-anchor" href="#philosophy" aria-label="Permalink to &quot;Philosophy&quot;">​</a></h1><p>BananaJS is built for teams who want <strong>serious structure</strong> without <strong>enterprise bloat</strong>. Four ideas drive the product:</p><h2 id="ai-first" tabindex="-1">AI-first <a class="header-anchor" href="#ai-first" aria-label="Permalink to &quot;AI-first&quot;">​</a></h2><p>Developer productivity is not optional. The <strong><code>bananajs</code></strong> CLI ships <strong>AI-assisted</strong> flows: generate from <strong>OpenAPI / JSON Schema</strong> or <strong>natural language</strong>, add <strong>JSDoc</strong>, and <strong>review</strong> controllers. <strong><code>bananajs ai setup</code></strong> writes <strong><code>.bananarc.json</code></strong>; the <strong><code>llm/</code></strong> provider layer supports <strong>Ollama</strong> (default), <strong>llama.cpp</strong>, <strong>OpenAI</strong>, and <strong>Anthropic</strong>. <strong><code>bananajs ai generate --module</code></strong> produces <strong>DDD-shaped</strong> domain, application, and infrastructure folders from a description or schema—so the framework meets teams where they work: specs, prompts, and automation—not only hand-written boilerplate.</p><h2 id="developer-experience-dx" tabindex="-1">Developer experience (DX) <a class="header-anchor" href="#developer-experience-dx" aria-label="Permalink to &quot;Developer experience (DX)&quot;">​</a></h2><p><strong>Decorators</strong> match how you already think about HTTP. <strong>Validation</strong> is declarative. <strong>Responses and errors</strong> are typed and consistent. <strong>OpenAPI</strong> is generated from the same decorators you ship. <strong>Plugins</strong> register with a clear lifecycle; <strong><code>BananaApp.create</code></strong> handles async setup. <strong>Testing</strong> gets a first-class <strong><code>BananaTestApp</code></strong> path. The goal is flow: less ceremony, fewer foot-guns, faster iteration—without hiding complexity when you need control.</p><h2 id="extendable-by-design" tabindex="-1">Extendable by design <a class="header-anchor" href="#extendable-by-design" aria-label="Permalink to &quot;Extendable by design&quot;">​</a></h2><p>The core stays lean; <strong>everything heavy is optional</strong>. <strong>Official plugins</strong> (TypeORM, Mongoose, OpenTelemetry, Zod, WebSocket) implement the same <strong><code>BananaPlugin</code></strong> contract as your own code. <strong>Auth, ABAC, tenancy, caching, metrics, uploads, rate limits</strong>—pluggable interfaces, not locked-in implementations. You extend the framework; it does not trap you in a single database or cloud story.</p><h2 id="domain-driven-design" tabindex="-1">Domain-driven design <a class="header-anchor" href="#domain-driven-design" aria-label="Permalink to &quot;Domain-driven design&quot;">​</a></h2><p><strong><code>@banana-universe/ddd</code></strong> provides <strong>Entity</strong>, <strong>ValueObject</strong>, <strong>AggregateRoot</strong>, <strong>Repository</strong> with <strong><code>FindCriteria</code></strong>, <strong>UnitOfWork</strong>, and <strong><code>@DomainService</code> / <code>@ApplicationService</code></strong>. Official ORM plugins ship <strong>repository adapters</strong> and transactional helpers. <strong><code>bananajs generate module</code></strong> (or <strong><code>ai generate --module</code></strong>) scaffolds <strong>domain / application / infrastructure</strong> layouts while adapters stay in infrastructure—generated, consistent, and documented.</p><hr><p>The stack covers security, multi-tenancy, plugins, observability, and AI-assisted CLI workflows, with <strong>schema-driven</strong> request validation. <strong><a href="/banana-universe/recipes/">Recipes</a></strong> in the repository walk through PostgreSQL, MongoDB, Fastify, WebSocket, and multi-tenant setups end-to-end.</p>',12)])])}const u=o(s,[["render",a]]);export{h as __pageData,u as default};
